edits.new_decoded_css:
.Navigation .search-actions ui-button { width:120px; height:20px; box-sizing:border-box; display:inline-flex; align-items:center; justify-content:center; border:1px solid #9c9c9c; border-radius:2px; background:linear-gradient(#fff,#e4e4e4); color:#333; line-height:18px; white-space:nowrap; user-select:none; cursor:pointer; }
.Navigation .search-actions ui-button:not([disabled]):hover { background:linear-gradient(#fff,#e2efff); border-color:#7d9abb; }
.Navigation .search-actions ui-button:not([disabled]):active { background:linear-gradient(#bfd5ef,#e1edfa); border-color:#627f9f; }
.Navigation .search-actions ui-button[disabled] { opacity:.5; cursor:default; }

